import type { TableRow } from '../../types/shared-table-types.js';
/** Extension interface for the TableState when useColumnSizes plugin is used. */
export interface UseExpandableRowState {
    /** State object keeping track of the expanded rows and ids. */
    expandedRows?: Record<string, boolean>;
    onRowsExpandedChange: (expandedRows: Record<string, boolean>) => void;
}
export interface UseExpandableRowRowProps {
    /** Virtualized row index accounting for additional expanded rows. */
    virtualizedIndex: number;
    /** Flag determining if the row is currently expanded. */
    isRowExpanded: boolean;
    /** Flag determining if the row can currently be expanded or not. */
    canExpandRow: boolean;
    /** Unique string id connecting the trigger with the expandable row. */
    ariaControls: string;
}
export interface UseExpandableRowColumnInstanceProps {
    /** Function defining if the current row can be expanded or not. */
    canExpand?: (row: TableRow<any>) => boolean;
}
export interface UseExpandableRowInstanceProps {
    /**
     * Callable function which can be used to toggle the expanded state
     * of a given row.
     */
    toggleExpandableRow: (id: string, value?: boolean) => void;
}
